class Solution {
    public int maximumGap(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;

        int min = nums[0];
        int max = nums[0];
        for (int value : nums) {
            min = Math.min(min, value);
            max = Math.max(max, value);
        }
        if (min == max) return 0;

        int bucketSize = Math.max(1, (int) Math.ceil((double) (max - min) / (n - 1)));
        int bucketCount = (max - min) / bucketSize + 1;
        int[] bucketMin = new int[bucketCount];
        int[] bucketMax = new int[bucketCount];
        boolean[] used = new boolean[bucketCount];
        java.util.Arrays.fill(bucketMin, Integer.MAX_VALUE);
        java.util.Arrays.fill(bucketMax, Integer.MIN_VALUE);

        for (int value : nums) {
            int index = (value - min) / bucketSize;
            bucketMin[index] = Math.min(bucketMin[index], value);
            bucketMax[index] = Math.max(bucketMax[index], value);
            used[index] = true;
        }

        int best = 0;
        int previousMax = min;
        for (int i = 0; i < bucketCount; i++) {
            if (!used[i]) continue;
            best = Math.max(best, bucketMin[i] - previousMax);
            previousMax = bucketMax[i];
        }
        return best;
    }
}

class Solution {
    public int maximumGap(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;

        int max = 0;
        for (int value : nums) {
            max = Math.max(max, value);
        }

        int[] buffer = new int[n];
        for (long exp = 1; exp <= max; exp *= 10) {
            int[] count = new int[10];
            for (int value : nums) {
                count[(int) ((value / exp) % 10)]++;
            }
            for (int i = 1; i < 10; i++) {
                count[i] += count[i - 1];
            }
            for (int i = n - 1; i >= 0; i--) {
                int digit = (int) ((nums[i] / exp) % 10);
                buffer[--count[digit]] = nums[i];
            }
            System.arraycopy(buffer, 0, nums, 0, n);
        }

        int best = 0;
        for (int i = 1; i < n; i++) {
            best = Math.max(best, nums[i] - nums[i - 1]);
        }
        return best;
    }
}

class Solution {
    public int maximumGap(int[] nums) {
        int n = nums.length;
        if (n < 2) return 0;

        int[] arr = nums;
        int[] buffer = new int[n];
        for (int shift = 0; shift < 32; shift += 8) {
            int[] count = new int[256];
            for (int value : arr) {
                count[(value >>> shift) & 255]++;
            }
            for (int i = 1; i < 256; i++) {
                count[i] += count[i - 1];
            }
            for (int i = n - 1; i >= 0; i--) {
                int value = arr[i];
                buffer[--count[(value >>> shift) & 255]] = value;
            }
            int[] temp = arr;
            arr = buffer;
            buffer = temp;
        }

        int best = 0;
        for (int i = 1; i < n; i++) {
            best = Math.max(best, arr[i] - arr[i - 1]);
        }
        return best;
    }
}

class Solution {
    public int maximumGap(int[] nums) {
        if (nums.length < 2) return 0;
        return maxGap(nums, 0, nums.length - 1, 30);
    }

    private int maxGap(int[] nums, int lo, int hi, int bit) {
        if (hi <= lo || bit < 0) return 0;

        int left = lo;
        int right = hi;
        while (left <= right) {
            while (left <= right && ((nums[left] >>> bit) & 1) == 0) left++;
            while (left <= right && ((nums[right] >>> bit) & 1) == 1) right--;
            if (left < right) {
                int temp = nums[left];
                nums[left] = nums[right];
                nums[right] = temp;
                left++;
                right--;
            }
        }

        if (right < lo) return maxGap(nums, left, hi, bit - 1);
        if (left > hi) return maxGap(nums, lo, right, bit - 1);

        int leftMax = nums[lo];
        for (int i = lo; i <= right; i++) {
            leftMax = Math.max(leftMax, nums[i]);
        }
        int rightMin = nums[left];
        for (int i = left; i <= hi; i++) {
            rightMin = Math.min(rightMin, nums[i]);
        }

        int crossGap = rightMin - leftMax;
        int leftGap = maxGap(nums, lo, right, bit - 1);
        int rightGap = maxGap(nums, left, hi, bit - 1);
        return Math.max(crossGap, Math.max(leftGap, rightGap));
    }
}
